<?php
if (session_status() !== PHP_SESSION_ACTIVE) session_start();
$preview = isset($_GET['preview']);
if ($preview) {
    $userId = 'DEMO-CUSTOMER';
    $customer = ['full_name' => 'Maria', 'loyalty_points' => 180];
    $activeOrder = ['quantity' => 2, 'container_size' => '5gal-round', 'delivery_status' => 'out for delivery', 'status' => 'approved'];
    $lastOrder = ['quantity' => 1, 'container_size' => '5gal-round', 'container_status' => 'existing', 'fulfillment_method' => 'delivery'];
} else {
    require_once '../config/database.php';
    require_once '../config/storage_service.php';
    require_once '../config/system_settings.php';
    $userId = (string)($_SESSION['customer_user_id'] ?? '');
    if ($userId === '') { header('Location: scan_qr.php'); exit; }
    require_once '../config/customer_order_access.php';
    require_customer_order_access($userId);
    $userStmt = $conn->prepare('SELECT user_id, full_name, status, loyalty_points FROM users WHERE user_id = ? LIMIT 1');
    $userStmt->bind_param('s', $userId); $userStmt->execute();
    $customer = $userStmt->get_result()->fetch_assoc();
    if (!$customer) { unset($_SESSION['customer_user_id']); header('Location: scan_qr.php'); exit; }
    if (strtolower((string)$customer['status']) !== 'approved') { header('Location: scan_qr.php?approval_required=' . urlencode((string)$customer['status'])); exit; }
    $activeStmt = $conn->prepare("SELECT transaction_id, quantity, container_size, container_status, fulfillment_method, status, delivery_status, created_at FROM transactions WHERE user_id = ? AND transaction_id NOT LIKE 'RWD-%' AND (status = 'pending' OR (status = 'approved' AND LOWER(COALESCE(delivery_status, 'pending')) <> 'delivered')) ORDER BY created_at DESC LIMIT 1");
    $activeStmt->bind_param('s', $userId); $activeStmt->execute(); $activeOrder = $activeStmt->get_result()->fetch_assoc();
    $lastStmt = $conn->prepare("SELECT quantity, container_size, container_status, fulfillment_method FROM transactions WHERE user_id = ? AND transaction_id NOT LIKE 'RWD-%' AND (LOWER(COALESCE(delivery_status, '')) = 'delivered' OR status = 'completed') ORDER BY created_at DESC LIMIT 1");
    $lastStmt->bind_param('s', $userId); $lastStmt->execute(); $lastOrder = $lastStmt->get_result()->fetch_assoc();
}
$sizeNames = ['5gal-round' => '19L Round', '5gal-slim' => '19L Slim', '2.5gal-slim' => '9.5L Slim'];
$firstName = trim(explode(' ', (string)$customer['full_name'])[0] ?? 'Customer');
$orderUrl = 'purchase.php?user_id=' . urlencode($userId);
if ($lastOrder) $orderUrl .= '&' . http_build_query(['container_size' => $lastOrder['container_size'], 'container' => $lastOrder['container_status'], 'quantity' => max(1, (int)$lastOrder['quantity']), 'fulfillment' => $lastOrder['fulfillment_method']]);
?>
