ion:none;font-size:.8rem;font-weight:800}.points{padding:24px;border:1px solid var(--line);border-radius:22px;background:#fff;box-shadow:0 10px 25px rgba(14,69,94,.05)}.points-icon{width:42px;height:42px;display:grid;place-items:center;border-radius:13px;color:#b6740c;background:#fff2d4}.points h2{margin:13px 0 5px;font-size:1.05rem}.points strong{display:block;color:#15699a;font:800 2rem Sora}.points p{margin:5px 0 16px;color:var(--muted);font-size:.78rem;line-height:1.5}.points a{color:#147fc7;text-decoration:none;font-size:.78rem;font-weight:800}.section-title{margin:34px 0 15px;font-size:1.1rem}.quick-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.quick{display:block;padding:19px;border:1px solid var(--line);border-radius:17px;color:var(--ink);background:#fff;text-decoration:none;transition:.2s}.quick:hover{transform:translateY(-3px);border-color:#58c5e1;box-shadow:0 13px 25px rgba(15,89,121,.09)}.quick i{display:grid;place-items:center;width:40px;height:40px;margin-bottom:14px;border-radius:12px;color:#1682bd;background:#e8f7fc}.quick:nth-child(2) i{color:#2562d1;background:#ecf0ff}.quick:nth-child(3) i{color:#0a9b76;background:#e5faf2}.quick h3{font-size:.92rem}.quick p{margin:6px 0 0;color:var(--muted);font-size:.76rem;line-height:1.5}.quick span{display:inline-block;margin-top:14px;color:#167dbc;font-size:.75rem;font-weight:800}.secondary{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:14px}.secondary a{display:flex;align-items:center;gap:10px;padding:15px;border:1px solid var(--line);border-radius:14px;color:#31546b;background:#fff;text-decoration:none;font-size:.82rem;font-weight:700}.secondary i{color:#1682bd}@media(max-width:800px){.layout{grid-template-columns:1fr}.quick-grid{grid-template-columns:1fr}.intro{display:block}.intro p{margin-top:12px}.page{padding-top:30px}}@media(max-width:480px){.nav,.page{padding-left:17px;padding-right:17px}.account{font-size:0}.account a{font-size:.82rem}.secondary{grid-template-columns: